import { readFile, writeFile } from "node:fs/promises";
import { createWorkspace, createForks } from "@tigrisdata/agent-kit";
import { put, get } from "@tigrisdata/storage";

async function main() {
  try {
    // 1. Read the current trial_id
    const trialIdRaw = await readFile("/logs/artifacts/trial_id", "utf-8");
    const trialId = trialIdRaw.trim().toLowerCase();
    console.log(`Trial ID: ${trialId}`);

    // 2. Build the editor workspace name
    const workspaceName = `harbor-ro-${trialId}`;
    console.log(`Workspace Name: ${workspaceName}`);

    // 3. Create the editor workspace
    console.log("Creating editor workspace...");
    const { data: workspaceData, error: workspaceError } = await createWorkspace(workspaceName, {
      ttl: { days: 1 },
      enableSnapshots: true,
      credentials: { role: "Editor" },
    });

    if (workspaceError) {
      console.error("Error creating workspace:", workspaceError);
      process.exit(1);
    }

    if (!workspaceData?.credentials) {
      console.error("Workspace credentials missing");
      process.exit(1);
    }

    const editorCreds = workspaceData.credentials;
    const workspaceBucket = workspaceName; // Assuming workspaceName is the bucket name

    // 4. Write notes/welcome.txt using editor credentials
    console.log("Writing notes/welcome.txt with editor credentials...");
    const { error: putError } = await put("notes/welcome.txt", "hello readonly", {
      config: {
        bucket: workspaceBucket,
        accessKeyId: editorCreds.accessKeyId,
        secretAccessKey: editorCreds.secretAccessKey,
      },
    });

    if (putError) {
      console.error("Error putting object with editor credentials:", putError);
      process.exit(1);
    }

    // 5. Create ReadOnly fork
    const forkPrefix = `harbor-ro-${trialId}-readonly`;
    console.log(`Creating ReadOnly fork with prefix: ${forkPrefix}...`);
    const { data: forkSet, error: forkError } = await createForks(workspaceBucket, 1, {
      prefix: forkPrefix,
      credentials: { role: "ReadOnly" },
    });

    if (forkError) {
      console.error("Error creating fork:", forkError);
      process.exit(1);
    }

    if (!forkSet?.forks?.[0]?.credentials) {
      console.error("Fork credentials missing");
      process.exit(1);
    }

    const readonlyCreds = forkSet.forks[0].credentials;
    const forkBucket = `harbor-ro-${trialId}-readonly-0`;
    console.log(`Fork Bucket: ${forkBucket}`);

    // 6. Attempt forbidden write with ReadOnly credentials
    console.log("Attempting forbidden write with ReadOnly credentials...");
    const { error: forbiddenError } = await put("notes/forbidden.txt", "should be rejected", {
      config: {
        bucket: forkBucket,
        accessKeyId: readonlyCreds.accessKeyId,
        secretAccessKey: readonlyCreds.secretAccessKey,
      },
    });

    if (!forbiddenError) {
      console.error("Error: Forbidden write unexpectedly succeeded!");
      process.exit(1);
    }

    console.log("Forbidden write correctly denied.");
    const denial = `${forbiddenError.name ?? "Error"}: ${forbiddenError.message ?? String(forbiddenError)} ${JSON.stringify(forbiddenError)}`;
    await writeFile("/home/user/tigris-task/write-denial.log", denial, "utf-8");

    // 7. Successful read with ReadOnly credentials
    console.log("Reading notes/welcome.txt with ReadOnly credentials...");
    const { data: readData, error: readError } = await get("notes/welcome.txt", "string", {
      config: {
        bucket: forkBucket,
        accessKeyId: readonlyCreds.accessKeyId,
        secretAccessKey: readonlyCreds.secretAccessKey,
      },
    });

    if (readError) {
      console.error("Error reading object with ReadOnly credentials:", readError);
      process.exit(1);
    }

    if (readData !== "hello readonly") {
      console.error(`Unexpected readback content: ${readData}`);
      process.exit(1);
    }

    console.log("Readback successful.");
    await writeFile("/home/user/tigris-task/readback.txt", readData, "utf-8");

    console.log("Task completed successfully.");
    process.exit(0);
  } catch (err) {
    console.error("Unexpected error in main:", err);
    process.exit(1);
  }
}

main();

